def get_position_meaning(card, position):
    """Return refined meaning for a card in a weekly/yearly position.

    position examples: environment, long_range, pluto, result, mercury, venus, mars, jupiter, saturn, uranus, neptune.
    """
    return WEEKLY_CARD_MEANINGS_REFINED.get(card, {}).get(str(position).lower())
